func (m *SessionsMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *SessionsMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockClearChangePasswordFailsDone() &&
		m.MinimockDeleteUserDone() &&
		m.MinimockDeleteUserExceptDone() &&
		m.MinimockRefundChangePasswordAttemptDone() &&
		m.MinimockSetPasswordEpochDone() &&
		m.MinimockTakeChangePasswordAttemptDone()
}
